438\u043a\u0430\u0442\u044b/\u0431\u0438\u0442\u044b\u0435 SMILES \u043e\u0446\u0435\u043d\u0438\u0432\u0430\u0442\u044c \u043d\u0435 \u043d\u0430 \u0447\u0451\u043c \u2014 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u043c \u043a\u0430\u043a \u00ab\u0434\u0430\u043d\u043d\u044b\u0435 \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u044e\u0442\u00bb. Proposed assumed-\u0441\u0445\u0435\u043c\u0430 \u0432\u0445\u043e\u0434\u0430: CSV/TSV \u0441 \u0437\u0430\u0433\u043e\u043b\u043e\u0432\u043a\u043e\u043c, UTF-8, \u043e\u0434\u043d\u0430 \u043c\u043e\u043b\u0435\u043a\u0443\u043b\u0430 \u0432 \u0441\u0442\u0440\u043e\u043a\u0435; \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u0430\u044f \u043a\u043e\u043b\u043e\u043d\u043a\u0430 SMILES (\u043f\u0440\u0438\u043d\u044f\u0442\u044c \u0438\u043c\u0435\u043d\u0430 \"smiles\"/\"SMILES\"/\"Canonical SMILES\"); \u043e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u044b\u0435 \u2014 \"name\"/\"compound_id\" \u0438 \u043a\u043e\u043b\u043e\u043d\u043a\u0430 \u0433\u0440\u0443\u043f\u043f\u044b.\n\n2) \u041e\u041a\u0420\u0423\u0416\u0415\u041d\u0418\u0415. python3 = Python 3.14.4; pip 25.1.1 \u0435\u0441\u0442\u044c. \u041f\u0440\u043e\u0432\u0435\u0440\u0435\u043d\u043e importlib.util.find_spec: \u041e\u0422\u0421\u0423\u0422\u0421\u0422\u0412\u0423\u042e\u0422 rdkit, datamol, pandas, numpy, scipy, seaborn, matplotlib, sklearn (polars, pyarrow \u2014 \u0442\u043e\u0436\u0435). \u041a\u044d\u0448\u0435\u0439 \u043f\u0430\u043a\u0435\u0442\u043e\u0432 \u043d\u0435\u0442 (\u0432 /usr/share/python-wheels \u0442\u043e\u043b\u044c\u043a\u043e setuptools/pip), \u0441\u0435\u0442\u044c \u043e\u0442\u043a\u043b\u044e\u0447\u0435\u043d\u0430 \u2192 \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u044c rdkit/pandas \u0432 \u044d\u0442\u043e\u0439 \u043f\u0435\u0441\u043e\u0447\u043d\u0438\u0446\u0435 \u041d\u0415\u0412\u041e\u0417\u041c\u041e\u0416\u041d\u041e; \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u0443\u0441\u0442\u0430\u043d\u0430\u0432\u043b\u0438\u0432\u0430\u043b, \u043a\u0430\u043a \u043f\u0440\u043e\u0441\u0438\u043b\u0438. \u0414\u043e\u0441\u0442\u0443\u043f\u043d\u044b stdlib: csv, json, sqlite3, statistics (\u043f\u0440\u043e\u0432\u0435\u0440\u0435\u043d\u043e \u0438\u043c\u043f\u043e\u0440\u0442\u043e\u043c). \u041e\u0433\u043e\u0432\u043e\u0440\u043a\u0430: \u0434\u0430\u0436\u0435 \u043f\u0440\u0438 \u0441\u0435\u0442\u0438 wheels rdkit \u043f\u043e\u0434 Python 3.14 \u043c\u043e\u0433\u0443\u0442 \u0431\u044b\u0442\u044c \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u044b \u2014 \u0440\u0438\u0441\u043a \u0434\u043b\u044f \u0440\u0435\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u0437\u0430\u043f\u0443\u0441\u043a\u0430.\n\n3) \u041f\u041b\u0410\u041d \u042d\u041a\u0421\u041f\u0415\u0420\u0418\u041c\u0415\u041d\u0422\u0410 (\u0442\u043e\u043b\u044c\u043a\u043e \u043f\u0440\u043e\u0435\u043a\u0442).\n   \u2014 \u041e\u0441\u043d\u043e\u0432\u043d\u043e\u0439 \u0441\u0442\u0435\u043a (\u043f\u0440\u0438 \u043d\u0430\u043b\u0438\u0447\u0438\u0438 \u043f\u0430\u043a\u0435\u0442\u043e\u0432): RDKit \u043a\u0430\u043a \u043a\u0430\u043d\u043e\u043d\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a \u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u043e\u0432 (\u043f\u0440\u043e\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u044b\u0439 \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442, \u0432\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u043c\u043e\u0441\u0442\u044c, \u0432\u0441\u0442\u0440\u043e\u0435\u043d\u043d\u044b\u0435 \u0432\u0430\u043b\u0438\u0434\u0430\u0442\u043e\u0440\u044b); \u043e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e datamol \u043a\u0430\u043a \u043e\u0431\u0451\u0440\u0442\u043a\u0430; pandas/numpy \u0434\u043b\u044f \u0442\u0430\u0431\u043b\u0438\u0446; matplotlib/seaborn \u0434\u043b\u044f \u0433\u0440\u0430\u0444\u0438\u043a\u043e\u0432.\n   \u2014 \u00ab\u0411\u0430\u0437\u043e\u0432\u044b\u0435 \u0441\u0432\u043e\u0439\u0441\u0442\u0432\u0430\u00bb (\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u0441\u043f\u0438\u0441\u043e\u043a): MolWt, HeavyAtomCount, \u043c\u043e\u043b\u0435\u043a\u0443\u043b\u044f\u0440\u043d\u0430\u044f \u0444\u043e\u0440\u043c\u0443\u043b\u0430 (rdMolDescriptors.CalcMolFormula), NumHDonors/NumHAcceptors (Lipinski), MolLogP, TPSA, NumRotatableBonds, NumAromaticRings + \u0434\u043e\u043b\u044f \u0430\u0440\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u0430\u0442\u043e\u043c\u043e\u0432, \u0441\u0443\u043c\u043c\u0430\u0440\u043d\u044b\u0439 \u0444\u043e\u0440\u043c\u0430\u043b\u044c\u043d\u044b\u0439 \u0437\u0430\u0440\u044f\u0434, \u0447\u0438\u0441\u043b\u043e N/O/S/P; Tanimoto \u043f\u043e Morgan-\u043e\u0442\u043f\u0435\u0447\u0430\u0442\u043a\u0430\u043c (radius=2, 2048 \u0431\u0438\u0442) \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u0440\u0438 \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u043e\u0441\u0442\u0438 \u0430\u043d\u0430\u043b\u0438\u0437\u0430 \u043f\u043e\u0445\u043e\u0436\u0435\u0441\u0442\u0438.\n   \u2014 \u041a\u043e\u043d\u0432\u0435\u0439\u0435\u0440: (\u0430) \u0447\u0442\u0435\u043d\u0438\u0435 \u0444\u0430\u0439\u043b\u0430, \u043d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f \u0438\u043c\u0451\u043d \u043a\u043e\u043b\u043e\u043d\u043e\u043a; (\u0431) MolFromSmiles \u0441 \u0440\u0430\u0437\u0434\u0435\u043b\u043e\u043c \u00ab\u0432\u0430\u043b\u0438\u0434\u043d\u044b\u0435/\u043d\u0435\u0432\u0430\u043b\u0438\u0434\u043d\u044b\u0435\u00bb; (\u0432) \u0441\u043c\u0435\u0441\u0438/\u0441\u043e\u043b\u0438 \u2014 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0439 \u0444\u0440\u0430\u0433\u043c\u0435\u043d\u0442 (\u0443\u0447\u0451\u0442 \u0442\u0430\u043a\u0438\u0445 \u0441\u0442\u0440\u043e\u043a); (\u0433) \u0440\u0430\u0441\u0447\u0451\u0442 \u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u043e\u0432; (\u0434) \u044d\u043a\u0441\u043f\u043e\u0440\u0442 descriptors.csv + \u043e\u0442\u0447\u0451\u0442 \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u0430 \u043f\u0430\u0440\u0441\u0438\u043d\u0433\u0430.\n   \u2014 \u041a\u043e\u043d\u0442\u0440\u043e\u043b\u044c\u043d\u044b\u0435 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438: \u0434\u043e\u043b\u044f \u0440\u0430\u0441\u043f\u0430\u0440\u0441\u0435\u043d\u043d\u044b\u0445 SMILES; \u0434\u0443\u0431\u043b\u0438\u043a\u0430\u0442\u044b \u043f\u043e \u043a\u0430\u043d\u043e\u043d\u0438\u0447\u0435\u0441\u043a\u043e\u043c\u0443 SMILES; \u043f\u0443\u0441\u0442\u044b\u0435/\u043a\u043e\u0440\u043e\u0442\u043a\u0438\u0435 \u0441\u0442\u0440\u043e\u043a\u0438; sanity-\u0434\u0438\u0430\u043f\u0430\u0437\u043e\u043d\u044b (MolWt \u2208 [50,2000], HeavyAtoms \u2265 1, |\u0437\u0430\u0440\u044f\u0434| \u2264 5); \u043a\u0440\u043e\u0441\u0441-\u0447\u0435\u043a \u0444\u043e\u0440\u043c\u0443\u043b\u044b \u043f\u0440\u043e\u0442\u0438\u0432 \u043f\u043e\u0434\u0441\u0447\u0451\u0442\u0430 \u0430\u0442\u043e\u043c\u043e\u0432; \u044e\u043d\u0438\u0442-\u0442\u0435\u0441\u0442 \u043d\u0430 ~10 \u044d\u0442\u0430\u043b\u043e\u043d\u043d\u044b\u0445 \u043c\u043e\u043b\u0435\u043a\u0443\u043b\u0430\u0445 \u0441 \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u044b\u043c\u0438 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f\u043c\u0438 (\u0430\u0441\u043f\u0438\u0440\u0438\u043d, \u043a\u043e\u0444\u0435\u0438\u043d, \u044d\u0442\u0430\u043d\u043e\u043b \u0438 \u0442.\u043f.).\n   \u2014 \u0421\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0430: \u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044f \u2014 \u043c\u0435\u0434\u0438\u0430\u043d\u0430, \u043a\u0432\u0430\u0440\u0442\u0438\u043b\u0438, IQR, \u0433\u0438\u0441\u0442\u043e\u0433\u0440\u0430\u043c\u043c\u044b; \u0433\u0440\u0443\u043f\u043f\u043e\u0432\u044b\u0435 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f \u2014 \u041a\u0440\u0430\u0441\u043a\u0435\u043b\u2013\u0423\u043e\u043b\u043b\u0438\u0441 + \u041c\u0430\u043d\u043d\u2013\u0423\u0438\u0442\u043d\u0438 \u0441 BH-FDR \u0438 \u0440\u0430\u0437\u043c\u0435\u0440\u043e\u043c \u044d\u0444\u0444\u0435\u043a\u0442\u0430 (\u041a\u043b\u0438\u0444\u0444\u0430 \u03b4); \u043a\u043e\u0440\u0440\u0435\u043b\u044f\u0446\u0438\u0438 \u2014 \u0421\u043f\u0438\u0440\u043c\u0435\u043d; \u043f\u0440\u0438 \u043c\u0430\u043b\u044b\u0445 \u0433\u0440\u0443\u043f\u043f\u0430\u0445 \u2014 \u043f\u0435\u0440\u0435\u0441\u0442\u0430\u043d\u043e\u0432\u043e\u0447\u043d\u044b\u0439 \u0442\u0435\u0441\u0442.\n   \u2014 \u041a\u0440\u0438\u0442\u0435\u0440\u0438\u0438 \u043f\u0440\u0438\u0433\u043e\u0434\u043d\u043e\u0441\u0442\u0438 (a priori): \u226595% SMILES \u043f\u0430\u0440\u0441\u044f\u0442\u0441\u044f; \u226580% \u043f\u043e\u043b\u043d\u043e\u0442\u044b \u043a\u043b\u044e\u0447\u0435\u0432\u044b\u0445 \u043f\u043e\u043b\u0435\u0439; \u043d\u0435\u0442 \u043a\u043e\u043d\u0441\u0442\u0430\u043d\u0442\u043d\u044b\u0445 \u043a\u043e\u043b\u043e\u043d\u043e\u043a; \u22655 \u043e\u0431\u044a\u0435\u043a\u0442\u043e\u0432 \u043d\u0430 \u0433\u0440\u0443\u043f\u043f\u0443. \u0418\u043d\u0430\u0447\u0435 \u2014 \u043e\u0442\u0447\u0451\u0442 \u043e \u043d\u0435\u043f\u0440\u0438\u0433\u043e\u0434\u043d\u043e\u0441\u0442\u0438 \u0432\u043c\u0435\u0441\u0442\u043e \u0430\u043d\u0430\u043b\u0438\u0437\u0430.\n   \u2014 Fallback \u0434\u043b\u044f \u0442\u0435\u043a\u0443\u0449\u0435\u0439 \u043f\u0435\u0441\u043e\u0447\u043d\u0438\u0446\u044b (\u0431\u0435\u0437 rdkit/pandas): \u0441\u043a\u0440\u0438\u043f\u0442 \u043f\u0438\u0448\u0435\u0442\u0441\u044f \u043f\u043e\u0434 RDKit-\u0441\u0442\u0435\u043a \u0438 \u0437\u0434\u0435\u0441\u044c \u0441\u0442\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u0442\u0441\u044f (\u0441\u0438\u043d\u0442\u0430\u043a\u0441\u0438\u0441, dry-run \u043d\u0430 \u0441\u0438\u043d\u0442\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u043c CSV-\u0437\u0430\u0433\u043b\u0443\u0448\u043a\u0435); \u0440\u0435\u0430\u043b\u044c\u043d\u044b\u0439 \u0440\u0430\u0441\u0447\u0451\u0442 \u2014 \u0432 \u043e\u043a\u0440\u0443\u0436\u0435\u043d\u0438\u0438 \u0441 RDKit. \u041b\u0438\u0431\u043e \u0447\u0435\u0441\u0442\u043d\u044b\u0439 stdlib-only \u043c\u0438\u043d\u0438\u043c\u0443\u043c (\u0430\u0442\u043e\u043c\u044b/\u041c\u041c \u043f\u043e \u0444\u043e\u0440\u043c\u0443\u043b\u0435) \u0441 \u044f\u0432\u043d\u043e\u0439 \u043f\u043e\u043c\u0435\u0442\u043a\u043e\u0439, \u0447\u0442\u043e logP/TPSA \u0431\u0435\u0437 RDKit \u043d\u0435 \u0432\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u044f\u0442\u0441\u044f.\n\n4) \u0414\u041e\u041f\u0423\u0429\u0415\u041d\u0418\u042f: assumed-\u0441\u0445\u0435\u043c\u0430 CSV \u0438\u0437 \u043f.1; \u0431\u0430\u0437\u043e\u0432\u044b\u0435 \u0441\u0432\u043e\u0439\u0441\u0442\u0432\u0430 = \u0441\u043f\u0438\u0441\u043e\u043a \u043f.3; \u0441\u043e\u043b\u0438 = \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0439 \u0444\u0440\u0430\u0433\u043c\u0435\u043d\u0442; \u0434\u0443\u0431\u043b\u0438 \u0443\u0434\u0430\u043b\u044f\u044e\u0442\u0441\u044f \u043f\u043e\u0441\u043b\u0435 \u043a\u0430\u043d\u043e\u043d\u0438\u043d\u0438\u0437\u0430\u0446\u0438\u0438; \u0441\u0435\u0442\u044c \u043e\u0442\u043a\u043b\u044e\u0447\u0435\u043d\u0430 \u2192 \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0430 \u043f\u0430\u043a\u0435\u0442\u043e\u0432 \u043d\u0435\u0432\u043e\u0437\u043c\u043e\u0436\u043d\u0430. \u041d\u0415\u041e\u041f\u0420\u0415\u0414\u0415\u041b\u0401\u041d\u041d\u041e\u0421\u0422\u0418: \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a/\u0444\u043e\u0440\u043c\u0430\u0442/\u0440\u0430\u0437\u043c\u0435\u0440 \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u0430 \u043d\u0435\u0438\u0437\u0432\u0435\u0441\u0442\u043d\u044b; \u0433\u0440\u0443\u043f\u043f\u043e\u0432\u043e\u0439 \u043f\u0440\u0438\u0437\u043d\u0430\u043a \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u0435\u0442; \u043e\u0436\u0438\u0434\u0430\u0435\u043c\u044b\u0439 \u044d\u043c\u043f\u0438\u0440\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u043d\u0435 \u0437\u0430\u0434\u0430\u043d \u0438 \u043d\u0435 \u0432\u044b\u0434\u0443\u043c\u044b\u0432\u0430\u0435\u0442\u0441\u044f; \u0431\u044e\u0434\u0436\u0435\u0442 \u0432\u0440\u0435\u043c\u0435\u043d\u0438 \u0440\u0430\u0441\u0447\u0451\u0442\u0430 \u043d\u0435 \u0437\u0430\u0434\u0430\u043d (\u043d\u0435 \u043d\u0430\u0437\u043d\u0430\u0447\u0430\u0435\u043c); rdkit\u00d7Python 3.14 \u043d\u0435 \u043f\u0440\u043e\u0432\u0435\u0440\u0435\u043d; \u043f\u043e\u0440\u043e\u0433 95% \u2014 \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u043d\u0430 \u0443\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u0438\u0435. \u0420\u0430\u0441\u0447\u0451\u0442 \u0441\u0432\u043e\u0439\u0441\u0442\u0432 \u043d\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u044f\u043b\u0441\u044f; \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442 \u043d\u0435 \u0437\u0430\u043f\u0443\u0441\u043a\u0430\u043b\u0441\u044f.", "assumptions": ["\u0425\u0438\u043c\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u0430 \u0432 \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0438 \u043d\u0435\u0442; \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u0442\u0441\u044f assumed-\u0441\u0445\u0435\u043c\u0430: CSV/TSV \u0441 \u0437\u0430\u0433\u043e\u043b\u043e\u0432\u043a\u043e\u043c, UTF-8, \u043a\u043e\u043b\u043e\u043d\u043a\u0430 SMILES (+ \u043e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e name/compound_id \u0438 \u0433\u0440\u0443\u043f\u043f\u043e\u0432\u043e\u0439 \u043f\u0440\u0438\u0437\u043d\u0430\u043a)", "\u041f\u043e\u0434 \u0431\u0430\u0437\u043e\u0432\u044b\u043c\u0438 \u0441\u0432\u043e\u0439\u0441\u0442\u0432\u0430\u043c\u0438 \u043f\u043e\u043d\u0438\u043c\u0430\u0435\u0442\u0441\u044f \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 RDKit-\u043d\u0430\u0431\u043e\u0440: MolWt, HeavyAtomCount, \u0444\u043e\u0440\u043c\u0443\u043b\u0430, NumHDonors/Acceptors, MolLogP, TPSA, NumRotatableBonds, \u0430\u0440\u043e\u043c\u0430\u0442\u0438\u0447\u043d\u043e\u0441\u0442\u044c, \u0444\u043e\u0440\u043c\u0430\u043b\u044c\u043d\u044b\u0435 \u0437\u0430\u0440\u044f\u0434\u044b; Tanimoto \u2014 \u043f\u043e \u0437\u0430\u043f\u0440\u043e\u0441\u0443", "\u0421\u043c\u0435\u0441\u0438/\u0441\u043e\u043b\u0438 \u043e\u0431\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u044e\u0442\u0441\u044f \u0432\u044b\u0431\u043e\u0440\u043e\u043c \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0435\u0433\u043e \u0444\u0440\u0430\u0433\u043c\u0435\u043d\u0442\u0430; \u0434\u0443\u0431\u043b\u0438\u043a\u0430\u0442\u044b \u0443\u0441\u0442\u0440\u0430\u043d\u044f\u044e\u0442\u0441\u044f \u043f\u043e \u043a\u0430\u043d\u043e\u043d\u0438\u0447\u0435\u0441\u043a\u043e\u043c\u0443 SMILES", "\u041a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 \u043f\u0440\u0438\u0433\u043e\u0434\u043d\u043e\u0441\u0442\u0438 >=95% \u0440\u0430\u0441\u043f\u0430\u0440\u0441\u0435\u043d\u043d\u044b\u0445 SMILES \u2014 \u043f\u0440\u0435\u0434\u043b\u0430\u0433\u0430\u0435\u043c\u044b\u0439 \u043f\u043e\u0440\u043e\u0433 \u043d\u0430 \u0443\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u0438\u0435 \u0438\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044f", "\u0421\u0435\u0442\u044c \u043e\u0442\u043a\u043b\u044e\u0447\u0435\u043d\u0430: \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0430 rdkit/pandas \u0432 \u0434\u0430\u043d\u043d\u043e\u0439 \u043f\u0435\u0441\u043e\u0447\u043d\u0438\u0446\u0435 \u043d\u0435\u0432\u043e\u0437\u043c\u043e\u0436\u043d\u0430; \u0440\u0435\u0430\