043d\u043d\u044b\u043c\u0438 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044f\u043c\u0438 \u2014 Lipinski HBD/HBA \u043f\u043e SMARTS, Crippen logP (Wildman\u2013Crippen 1999), TopoPSA (Ertl 2000), \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u043d\u0430\u044f \u043c\u043e\u0434\u0435\u043b\u044c \u0430\u0440\u043e\u043c\u0430\u0442\u0438\u0447\u043d\u043e\u0441\u0442\u0438; (2) \u0432\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u043c\u043e\u0441\u0442\u044c: \u0432\u0435\u0440\u0441\u0438\u044f RDKit \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0438 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f \u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u044b; (3) \u0432\u0441\u0442\u0440\u043e\u0435\u043d\u043d\u044b\u0435 \u0432\u0430\u043b\u0438\u0434\u0430\u0446\u0438\u044f/\u0441\u0430\u043d\u0438\u0442\u0438\u0437\u0430\u0446\u0438\u044f SMILES \u0438 \u043a\u0430\u043d\u043e\u043d\u0438\u043d\u0438\u0437\u0430\u0446\u0438\u044f, \u0447\u0442\u043e \u0441\u0430\u043c\u043e \u043f\u043e \u0441\u0435\u0431\u0435 \u2014 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u0430 \u0434\u0430\u043d\u043d\u044b\u0445. \u0412\u0441\u043f\u043e\u043c\u043e\u0433\u0430\u0442\u0435\u043b\u044c\u043d\u043e: pandas/numpy (\u0442\u0430\u0431\u043b\u0438\u0446\u044b/\u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0430), matplotlib/seaborn (\u0433\u0440\u0430\u0444\u0438\u043a\u0438, \u0435\u0441\u043b\u0438 \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u044b); datamol \u2014 \u043e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e, \u0442\u043e\u043b\u044c\u043a\u043e \u043a\u0430\u043a \u0442\u043e\u043d\u043a\u0430\u044f \u043e\u0431\u0451\u0440\u0442\u043a\u0430 (\u0435\u0433\u043e \u0430\u0433\u0440\u0435\u0433\u0430\u0442\u043e\u0440\u043d\u044b\u0435 \u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u044f \u0442\u0440\u0443\u0434\u043d\u0435\u0435 \u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b\u0438\u0440\u043e\u0432\u0430\u0442\u044c, \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u0440\u0435\u0444\u0435\u0440\u0435\u043d\u0441 \u2014 \u00ab\u0433\u043e\u043b\u044b\u0439\u00bb RDKit).\n\u041e\u0413\u0420\u0410\u041d\u0418\u0427\u0415\u041d\u0418\u0415 \u041f\u0415\u0420\u0415\u041d\u041e\u0421\u0418\u041c\u041e\u0421\u0422\u0418 (\u043d\u0435 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0430): \u0432 \u0442\u0435\u043a\u0443\u0449\u0435\u0439 \u043f\u0435\u0441\u043e\u0447\u043d\u0438\u0446\u0435 RDKit/pandas/numpy/scipy/matplotlib/seaborn \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u044e\u0442, \u0441\u0435\u0442\u044c \u043e\u0442\u043a\u043b\u044e\u0447\u0435\u043d\u0430, \u043a\u044d\u0448\u0435\u0439 \u043f\u0430\u043a\u0435\u0442\u043e\u0432 \u043d\u0435\u0442 \u2192 \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0430 \u043d\u0435\u0432\u043e\u0437\u043c\u043e\u0436\u043d\u0430; \u043a\u0440\u043e\u043c\u0435 \u0442\u043e\u0433\u043e, \u0441\u043e\u0432\u043c\u0435\u0441\u0442\u0438\u043c\u043e\u0441\u0442\u044c \u0431\u0438\u043d\u0430\u0440\u043d\u044b\u0445 wheels RDKit \u0441 Python 3.14.4 \u043d\u0435 \u043f\u0440\u043e\u0432\u0435\u0440\u0435\u043d\u0430 (\u043d\u0430 \u043c\u043e\u043c\u0435\u043d\u0442 \u0434\u0438\u0437\u0430\u0439\u043d\u0430 \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0430 3.14 \u043d\u0435 \u0432\u0435\u0440\u0438\u0444\u0438\u0446\u0438\u0440\u043e\u0432\u0430\u043d\u0430). \u042d\u0442\u043e \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0438\u0432\u0430\u0435\u0442 \u043c\u0435\u0441\u0442\u043e \u0438\u0441\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u044f \u043a\u043e\u043d\u0432\u0435\u0439\u0435\u0440\u0430, \u043d\u043e \u043d\u0435 \u043a\u043e\u0440\u0440\u0435\u043a\u0442\u043d\u043e\u0441\u0442\u044c\u8bbe\u8ba1\u65b9\u6848: \u0440\u0430\u0441\u0447\u0451\u0442 \u0432\u044b\u043f\u043e\u043b\u043d\u044f\u0435\u0442\u0441\u044f \u0432 \u043e\u043a\u0440\u0443\u0436\u0435\u043d\u0438\u0438 \u0441 RDKit (conda-forge rdkit, \u0432\u0435\u0440\u0441\u0438\u044f \u043f\u0438\u043d\u0438\u0442\u0441\u044f), \u043f\u0435\u0441\u043e\u0447\u043d\u0438\u0446\u0430 \u0433\u043e\u0434\u0438\u0442\u0441\u044f \u0434\u043b\u044f \u043d\u0430\u043f\u0438\u0441\u0430\u043d\u0438\u044f/\u0441\u0442\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438 \u043a\u043e\u0434\u0430 \u0438 dry-run'\u043e\u0432 \u043d\u0430 \u0437\u0430\u0433\u043b\u0443\u0448\u043a\u0430\u0445.\n\n\u2550\u2550\u2550 2. \u0412\u0425\u041e\u0414\u041d\u042b\u0415 \u0414\u0410\u041d\u041d\u042b\u0415 (ASSUMED-\u0421\u0425\u0415\u041c\u0410) \u2550\u2550\u2550\nCSV/TSV, UTF-8, \u0441 \u0437\u0430\u0433\u043e\u043b\u043e\u0432\u043a\u043e\u043c, \u043e\u0434\u043d\u0430 \u043c\u043e\u043b\u0435\u043a\u0443\u043b\u0430 = \u043e\u0434\u043d\u0430 \u0441\u0442\u0440\u043e\u043a\u0430. \u041e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u0430 \u043a\u043e\u043b\u043e\u043d\u043a\u0430 SMILES (\u0430\u043b\u0438\u0442\u0438\u0437\u044b \u0438\u043c\u0451\u043d: smiles/SMILES/Canonical SMILES/canonical_smiles). \u041e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e: name/compound_id (\u0438\u0434\u0435\u043d\u0442\u0438\u0444\u0438\u043a\u0430\u0442\u043e\u0440), group (\u043f\u0440\u0438\u0437\u043d\u0430\u043a \u0433\u0440\u0443\u043f\u043f\u0438\u0440\u043e\u0432\u043a\u0438 \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u0440\u0438 \u0435\u0433\u043e \u043d\u0430\u043b\u0438\u0447\u0438\u0438 \u0438 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u0438\u0438 \u0437\u0430\u043a\u0430\u0437\u0447\u0438\u043a\u043e\u043c). \u0420\u0430\u0437\u0434\u0435\u043b\u0438\u0442\u0435\u043b\u044c \u0430\u0432\u0442\u043e-\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u044f\u0435\u0442\u0441\u044f (csv.Sniffer, fallback \u2014 \u0442\u0430\u0431). \u0415\u0441\u043b\u0438 \u0437\u0430\u043a\u0430\u0437\u0447\u0438\u043a \u043f\u0435\u0440\u0435\u0434\u0430\u0441\u0442 SDF/SDT \u2014 \u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u044b \u0431\u0435\u0440\u0443\u0442\u0441\u044f \u0438\u0437 \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u044b, \u043c\u043e\u043b\u0435\u043a\u0443\u043b\u044f\u0440\u043d\u0430\u044f \u0444\u043e\u0440\u043c\u0443\u043b\u0430 \u043a\u0430\u043a \u0441\u0432\u043e\u0439\u0441\u0442\u0432\u043e \u043d\u0435 \u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044f \u0438\u0437 \u0442\u0435\u0433\u0430.\n\n\u2550\u2550\u2550 3. \u0421\u041f\u0415\u0426\u0418\u0424\u0418\u041a\u0410\u0426\u0418\u042f \u0411\u0410\u0417\u041e\u0412\u042b\u0425 \u0421\u0412\u041e\u0419\u0421\u0422\u0412 \u2550\u2550\u2550\n\u041f\u0440\u043e\u0442\u043e\u043a\u043e\u043b \u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e (ASSUMPTION, \u0437\u0430\u043a\u0430\u0437\u0447\u0438\u043a\u043e\u043c \u043d\u0435 \u0437\u0430\u0434\u0430\u043d): SMILES \u043a\u0430\u043a \u0435\u0441\u0442\u044c; \u0441\u043c\u0435\u0441\u0438/\u0441\u043e\u043b\u0438 \u2192 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0439 \u0444\u0440\u0430\u0433\u043c\u0435\u043d\u0442 (\u0447\u0438\u0441\u043b\u043e \u0437\u0430\u0442\u0440\u043e\u043d\u0443\u0442\u044b\u0445 \u0441\u0442\u0440\u043e\u043a \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f); \u0431\u0435\u0437 \u043f\u0440\u043e\u0442\u043e\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f \u043f\u0440\u0438 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u043c pH; \u0431\u0435\u0437 \u043a\u0430\u043d\u043e\u043d\u0438\u043d\u0438\u0437\u0430\u0446\u0438\u0438 \u0442\u0430\u0443\u0442\u043e\u043c\u0435\u0440\u043e\u0432; \u0441\u0442\u0435\u0440\u0435\u043e\u0445\u0438\u043c\u0438\u044f \u0441\u043e\u0445\u0440\u0430\u043d\u044f\u0435\u0442\u0441\u044f; \u041d \u2014 \u043d\u0435\u044f\u0432\u043d\u044b\u0435; \u0432\u0435\u0440\u0441\u0438\u0438: Python 3.x, RDKit (\u043f\u0438\u043d), \u0432\u044b\u0437\u043e\u0432\u044b \u2014 \u0434\u0435\u0444\u043e\u043b\u0442\u043d\u044b\u0435 \u0432\u0430\u0440\u0438\u0430\u043d\u0442\u044b \u0444\u0443\u043d\u043a\u0446\u0438\u0439. \u041e\u0442\u043a\u043b\u043e\u043d\u0435\u043d\u0438\u0435 \u043e\u0442 \u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b\u0430 (\u0438\u043e\u043d\u043d\u044b\u0435 \u0444\u043e\u0440\u043c\u044b, \u0442\u0430\u0443\u0442\u043e\u043c\u0435\u0440\u044b) \u043c\u0435\u043d\u044f\u0435\u0442 HBD/HBA, TPSA, \u0437\u0430\u0440\u044f\u0434 \u2014 \u044d\u0442\u043e \u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b\u044c\u043d\u0430\u044f \u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c, \u0430 \u043d\u0435 \u043e\u0448\u0438\u0431\u043a\u0430.\n\n| \u0421\u0432\u043e\u0439\u0441\u0442\u0432\u043e | \u0412\u044b\u0437\u043e\u0432 RDKit | \u0415\u0434. | \u0422\u0438\u043f | \u041e\u0441\u043c\u044b\u0441\u043b\u0435\u043d\u043d\u0430\u044f \u043e\u0431\u043b\u0430\u0441\u0442\u044c / \u043f\u0440\u0438\u043c\u0435\u0447\u0430\u043d\u0438\u044f |\n| \u041c\u043e\u043b\u0435\u043a\u0443\u043b\u044f\u0440\u043d\u0430\u044f \u0444\u043e\u0440\u043c\u0443\u043b\u0430 | rdMolDescriptors.CalcMolFormula | \u2014 | \u0441\u0442\u0440\u043e\u043a\u0430/\u043a\u0430\u0442\u0435\u0433\u043e\u0440\u0438\u0430\u043b\u044c\u043d\u0430\u044f (Hill) | \u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043e\u0442 \u0441\u043e\u043b\u044c\u0432\u0430\u0442\u043d\u043e\u0439 \u0444\u043e\u0440\u043c\u044b/\u043f\u0440\u043e\u0442\u043e\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f |\n| MolWt | Descriptors.MolWt | \u0433/\u043c\u043e\u043b\u044c (\u0441\u0440\u0435\u0434\u043d\u044f\u044f) | \u043d\u0435\u043f\u0440\u0435\u0440\u044b\u0432\u043d\u0430\u044f | ~50\u20131500 \u0434\u043b\u044f \u00ab\u043b\u0435\u043a\u0430\u0440\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0445\u00bb; \u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u043a \u0441\u043e\u043b\u044f\u043c |\n| HeavyAtomCount | rdMolDescriptors.CalcNumHeavyAtoms | \u2014 | \u0441\u0447\u0451\u0442\u043d\u0430\u044f | \u22651; \u043d\u0435 \u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043e\u0442 H |\n| NumHDonors / NumHAcceptors | rdMolDescriptors.CalcNumHDonors / CalcNumHAcceptors (Lipinski-SMARTS) | \u2014 | \u0441\u0447\u0451\u0442\u043d\u044b\u0435 | 0\u2013~12 / 0\u2013~20; \u0437\u0430\u0432\u0438\u0441\u044f\u0442 \u043e\u0442 \u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b\u0430 (\u043f\u0440\u043e\u0442\u043e\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435/\u0442\u0430\u0443\u0442\u043e\u043c\u0435\u0440\u044b/\u0437\u0430\u0440\u044f\u0434) |\n| MolLogP | Descriptors.MolLogP (Crippen) | log10(\u043e\u043a\u0442/\u0432\u043e\u0434\u0430), \u0431.\u0435. | \u043d\u0435\u043f\u0440\u0435\u0440\u044b\u0432\u043d\u0430\u044f | ~ \u22123\u2026+10; \u0441\u043b\u0430\u0431\u0430\u044f \u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u044c \u043e\u0442 \u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b\u0430 |\n| TPSA | rdMolDescriptors.CalcTPSA (TopoPSA) | \u00c5\u00b2 | \u043d\u0435\u043f\u0440\u0435\u0440\u044b\u0432\u043d\u0430\u044f | 0\u2013~250; \u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043e\u0442 \u0437\u0430\u0440\u044f\u0434\u0430/\u0442\u0430\u0443\u0442\u043e\u043c\u0435\u0440\u043e\u0432 |\n| NumRotatableBonds | rdMolDescriptors.CalcNumRotatableBonds (\u0434\u0435\u0444\u043e\u043b\u0442; \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u0432\u0435\u0440\u0441\u0438\u0438 \u22652020.09) | \u2014 | \u0441\u0447\u0451\u0442\u043d\u0430\u044f | 0\u2013~20; \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0432 \u043e\u0442\u0447\u0451\u0442\u0435 |\n| NumAromaticRings + \u0430\u0440\u043e\u043c\u0430\u0442\u0438\u0447.\u0444\u043b\u0430\u0433 | rdMolDescriptors.CalcNumAromaticRings; any(a.GetIsAromatic()) | \u2014 / \u0431\u0443\u043b\u0435\u0432\u043e | \u0441\u0447\u0451\u0442\u043d\u0430\u044f / \u043a\u0430\u0442\u0435\u0433\u043e\u0440\u0438\u0430\u043b\u044c\u043d\u0430\u044f | \u043c\u043e\u0434\u0435\u043b\u044c \u0430\u0440\u043e\u043c\u0430\u0442\u0438\u0447\u043d\u043e\u0441\u0442\u0438 RDKit \u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e (\u0437\u0430\u0434\u0430\u0442\u044c \u044f\u0432\u043d\u043e model=ARDataset default) |\n| FractionCSP3 | rdMolDescriptors.CalcFractionCSP3 | \u0434\u043e\u043b\u044f | \u043d\u0435\u043f\u0440\u0435\u0440\u044b\u0432\u043d\u0430\u044f | [0;1] |\n| \u0424\u043e\u0440\u043c\u0430\u043b\u044c\u043d\u044b\u0439 \u0437\u0430\u0440\u044f\u0434 | Chem.GetFormalCharge | \u2014 | \u0446\u0435\u043b\u0430\u044f \u0441\u0447\u0451\u0442\u043d\u0430\u044f | sanity |\u03a3|\u22645; \u043f\u0440\u044f\u043c\u043e \u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043e\u0442 \u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b\u0430 |\n| \u0427\u0438\u0441\u043b\u0430 N,O,S,P | Chem.rdMolDescriptors / Counter \u043f\u043e \u0430\u0442\u043e\u043c\u0430\u043c | \u2014 | \u0441\u0447\u0451\u0442\u043d\u044b\u0435 | \u22650 |\n| Tanimoto (\u043f\u043e \u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u044e) | rdFingerprintGenerator.GetMorganGenerator(radius=2, fpSize=2048) + DataStructures.TanimotoSimilarity | \u0434\u043e\u043b\u044f | \u043d\u0435\u043f\u0440\u0435\u0440\u044b\u0432\u043d\u0430\u044f | [0;1]; \u0441\u0447\u0438\u0442\u0430\u0442\u044c \u0442\u043e\u043b\u044c\u043a\u043e \u0435\u0441\u043b\u0438 \u0437\u0430\u043a\u0430\u0437\u0447\u0438\u043a\u0443 \u043d\u0443\u0436\u0435\u043d \u0430\u043d\u0430\u043b\u0438\u0437 \u043f\u043e\u0445\u043e\u0436\u0435\u0441\u0442\u0438 |\n\n\u2550\u2550\u2550 4. \u041a\u041e\u041d\u0422\u0420\u041e\u041b\u0418 (\u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u043c\u044b\u0439 \u043f\u0435\u0440\u0435\u0447\u0435\u043d\u044c; \u043f\u0440\u043e\u0432\u0430\u043b \u2192 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435) \u2550\u2550\u2550\nC1 \u0414\u043e\u043b\u044f \u043d\u0435\u043f\u0440\u043e\u0441\u043f\u0430\u0440\u0441\u0435\u043d\u043d\u044b\u0445 SMILES (MolFromSmiles=None). \u041f\u043e\u0440\u043e\u0433 (\u043a\u043e\u043d\u0432\u0435\u043d\u0446\u0438\u044f, \u0441\u043e\u0433\u043b\u0430\u0441\u0443\u0435\u0442\u0441\u044f, \u043d\u0435 \u044d\u043c\u043f\u0438\u0440\u0438\u043a\u0430): \u226595% \u0443\u0441\u043f\u0435\u0445. \u041f\u0440\u043e\u0432\u0430\u043b \u2192 \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0430, QC-\u043e\u0442\u0447\u0451\u0442 \u0441\u043e \u0441\u043f\u0438\u0441\u043a\u043e\u043c \u0438 \u043a\u043b\u0430\u0441\u0442\u0435\u0440\u0438\u0437\u0430\u0446\u0438\u0435\u0439 \u043e\u0442\u043a\u0430\u0437\u043e\u0432, \u0431\u0435\u0437 \u0430\u043d\u0430\u043b\u0438\u0437\u0430.\nC2 \u0414\u0443\u0431\u043b\u0438\u043a\u0430\u0442\u044b \u043f\u043e \u043a\u0430\u043d\u043e\u043d\u0438\u0447\u0435\u0441\u043a\u043e\u043c\u0443 SMILES. \u0414\u0435\u0439\u0441\u0442\u0432\u0438\u0435: \u0443\u0434\u0430\u043b\u0435\u043d\u0438\u0435 \u0441 \u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b\u043e\u043c N_dup; N_dup>10% \u2192 \u0437\u0430\u043f\u0440\u043e\u0441 \u0437\u0430\u043a\u0430\u0437\u0447\u0438\u043a\u0443 (\u0432\u043e\u0437\u043c\u043e\u0436\u043d\u0430 \u043e\u0448\u0438\u0431\u043a\u0430 \u0432\u044b\u0433\u0440\u0443\u0437\u043a\u0438).\nC3 Sanity-\u0434\u0438\u0430\u043f\u0430\u0437\u043e\u043d\u044b: MolWt\u2208[50,2000] (\u0434\u043b\u044f \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u0430; \u044d\u0442\u0430\u043b\u043e\u043d\u043d\u044b\u0435 \u0442\u0435\u0441\u0442-\u043c\u043e\u043b\u0435\u043a\u0443\u043b\u044b \u0432\u0440\u043e\u0434\u0435 \u044d\u0442\u0430\u043d\u043e\u043b\u0430 \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u044e\u0442\u0441\u044f \u0432\u043d\u0435 \u044d\u0442\u043e\u0433\u043e \u0444\u0438\u043b\u044c\u0442\u0440\u0430), HeavyAtoms\u22651, |\u03a3\u0437\u0430\u0440\u044f\u0434|\u22645, TPSA\u2208(0,500]. \u041f\u0440\u043e\u0432\u0430\u043b \u0441\u0442\u0440\u043e\u043a\u0438 \u2192 \u0438\u0441\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u0435 \u0438\u0437 \u0430\u043d\u0430\u043b\u0438\u0437\u0430, \u0443\u0447\u0451\u0442, \u043f\u043e\u0432\u0442\u043e\u0440 \u0432 sensitivity-\u0440\u0435\u0436\u0438\u043c\u0435 \u00ab\u0441\u043e \u0432\u043a\u043b\u044e\u0447\u0451\u043d\u043d\u044b\u043c\u0438\u00bb.\nC4 \u041a\u0440\u043e\u0441\u0441-\u0447\u0435\u043a \u0444\u043e\u0440\u043c\u0443\u043b\u044b: \u043f\u0430\u0440\u0441\u0438\u043d\u0433 CalcMolFormula \u043f\u0440\u043e\u0442\u0438\u0432 \u043f\u0440\u044f\u043c\u043e\u0433\u043e \u043f\u043e\u0434\u0441\u0447\u0451\u0442\u0430 \u0430\u0442\u043e\u043c\u043e\u0432 \u043c\u043e\u043b\u0430 (\u043f\u043e\u044d\u043b\u0435\u043c\u0435\u043d\u0442\u043d\u043e, \u0432\u043a\u043b\u044e\u0447\u0430\u044f \u044f\u0432\u043d\u044b\u0435 H). \u0420\u0430\u0441\u0445\u043e\u0436\u0434\u0435\u043d\u0438\u0435 \u2192 \u0431\u0430\u0433 \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438/\u0441\u0430\u043d\u0438\u0442\u0438\u0437\u0430\u0446\u0438\u0438, \u0421\u0422\u041e\u041f.\nC5 \u042e\u043d\u0438\u0442-\u0442\u0435\u0441\u0442 \u043d\u0430 \u044d\u0442\u0430\u043b\u043e\u043d\u043d\u044b\u0445 \u043c\u043e\u043b\u0435\u043a\u0443\u043b\u0430\u0445 \u0441 \u043e\u043f\u0443\u0431\u043b\u0438\u043a\u043e\u0432\u0430\u043d\u043d\u044b\u043c\u0438 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f\u043c\u0438 (\u0430\u0441\u043f\u0438\u0440\u0438\u043d C9H8O4, MW 180.16, HBD 1, HBA 4, TPSA 63.6\u00b11, rotbonds 3; \u043a\u043e\u0444\u0435\u0438\u043d C8H10N4O2, MW 194.19, HBD 0, HBA 3, TPSA 58.4\u00b11; \u044d\u0442\u0430\u043d\u043e\u043b C2H6O, MW 46.07, HBD/HBA 1/1, TPSA 20.2\u00b11, rotbonds 0; \u0433\u043b\u044e\u043a\u043e\u04