u044b\u0435: \u043c\u0435\u0434\u0438\u0430\u043d\u0430 [Q1\u2013Q3], IQR, min/max, N_missing \u043f\u043e \u043a\u0430\u0436\u0434\u043e\u043c\u0443 \u0441\u0432\u043e\u0439\u0441\u0442\u0432\u0443; \u0433\u0438\u0441\u0442\u043e\u0433\u0440\u0430\u043c\u043c\u044b \u0441 \u0431\u0438\u043d\u043e\u0432\u0430\u043d\u0438\u0435\u043c Freedman\u2013Diaconis.\n(b) \u041a\u043e\u0440\u0440\u0435\u043b\u044f\u0446\u0438\u0438: \u0421\u043f\u0438\u0440\u043c\u0435\u043d \u043f\u043e\u043f\u0430\u0440\u043d\u043e \u043c\u0435\u0436\u0434\u0443 \u0447\u0438\u0441\u043b\u043e\u0432\u044b\u043c\u0438 \u0441\u0432\u043e\u0439\u0441\u0442\u0432\u0430\u043c\u0438; m \u0434\u043b\u044f BH-FDR = \u0444\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0435 \u0447\u0438\u0441\u043b\u043e \u043f\u0435\u0440\u0435\u0434\u0430\u043d\u043d\u044b\u0445 \u0432 bh() p-value, \u0442.\u0435. d(d\u22121)/2 \u0434\u043b\u044f d \u0441\u0432\u043e\u0439\u0441\u0442\u0432 (\u043f\u0435\u0440\u0435\u0441\u0447\u0438\u0442\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0441\u043a\u0440\u0438\u043f\u0442\u043e\u043c, \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0432 \u043e\u0442\u0447\u0451\u0442\u0435).\n(c) \u0413\u0440\u0443\u043f\u043f\u043e\u0432\u044b\u0435 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f \u2014 \u0422\u041e\u041b\u042c\u041a\u041e \u043f\u0440\u0438 \u043d\u0430\u043b\u0438\u0447\u0438\u0438 \u043a\u043e\u043b\u043e\u043d\u043a\u0438 group, \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0451\u043d\u043d\u043e\u0439 \u0437\u0430\u043a\u0430\u0437\u0447\u0438\u043a\u043e\u043c; \u0438\u043d\u0430\u0447\u0435 \u0430\u043d\u0430\u043b\u0438\u0437 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u043e\u043f\u0438\u0441\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u043c + \u043a\u043e\u0440\u0440\u0435\u043b\u044f\u0446\u0438\u0438 (\u044f\u0432\u043d\u0430\u044f \u0441\u0442\u0440\u043e\u043a\u0430 \u0432 \u043e\u0442\u0447\u0451\u0442\u0435 \u00ab\u043f\u0440\u0438\u0437\u043d\u0430\u043a \u0433\u0440\u0443\u043f\u043f\u0438\u0440\u043e\u0432\u043a\u0438 \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u0435\u0442\u00bb). \u0418\u0435\u0440\u0430\u0440\u0445\u0438\u044f: Kruskal\u2013Wallis \u043f\u043e \u0441\u0432\u043e\u0439\u0441\u0442\u0432\u0443; \u043f\u0440\u0438 p<0.05 \u2014 \u043f\u043e\u043f\u0430\u0440\u043d\u044b\u0435 Mann\u2013Whitney U, \u043f\u043e\u0441\u0442-\u0445\u043e\u043a \u0442\u043e\u043b\u044c\u043a\u043e \u0434\u043b\u044f \u0433\u0440\u0443\u043f\u043f, \u043f\u0440\u043e\u0448\u0435\u0434\u0448\u0438\u0445 \u00ab\u0448\u043b\u044e\u0437\u00bb KW. m \u0434\u043b\u044f FDR = (\u0447\u0438\u0441\u043b\u043e \u0441\u0432\u043e\u0439\u0441\u0442\u0432) \u00d7 (\u0447\u0438\u0441\u043b\u043e \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u043d\u044b\u0445 \u043f\u043e\u043f\u0430\u0440\u043d\u044b\u0445 \u0442\u0435\u0441\u0442\u043e\u0432) \u2014 \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044f \u0438\u0437 \u0444\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u0430 p-value; \u043a\u043e\u0440\u0440\u0435\u043a\u0446\u0438\u044f BH q<0.05. \u0420\u0430\u0437\u043c\u0435\u0440 \u044d\u0444\u0444\u0435\u043a\u0442\u0430: Cliff's \u03b4 (\u043f\u043e\u0440\u043e\u0433\u0438 0.147/0.33/0.474) + \u0440\u0430\u043d\u0433\u043e\u0432\u0430\u044f r \u0434\u043b\u044f KW.\n(d) \u0412\u044b\u0440\u043e\u0436\u0434\u0451\u043d\u043d\u044b\u0435 \u043a\u043e\u043b\u043e\u043d\u043a\u0438: 0 \u0434\u0438\u0441\u043f\u0435\u0440\u0441\u0438\u0438/1 \u0443\u043d\u0438\u043a\u0430\u043b\u044c\u043d\u044b\u0439 \u0443\u0440\u043e\u0432\u0435\u043d\u044c \u2192 \u0438\u0441\u043a\u043b\u044e\u0447\u0438\u0442\u044c \u0438\u0437 \u043a\u043e\u0440\u0440\u0435\u043b\u044f\u0446\u0438\u0439 \u0438 \u0442\u0435\u0441\u0442\u043e\u0432, \u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c \u0432 \u043e\u043f\u0438\u0441\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0439 \u0442\u0430\u0431\u043b\u0438\u0446\u0435 \u0441 \u043f\u043e\u043c\u0435\u0442\u043a\u043e\u0439; mode-\u0447\u0430\u0441\u0442\u043e\u0442\u0430 >99% \u2192 \u0442\u043e\u043b\u044c\u043a\u043e \u043e\u043f\u0438\u0441\u0430\u0442\u0435\u043b\u044c\u043d\u043e.\n(e) \u041f\u0440\u0430\u0432\u044b\u0439 \u0441\u043a\u043e\u0441: \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 |skewness|>2 \u0418\u041b\u0418 max/Q3>10 \u2192 \u0434\u043e\u0431\u0430\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u043b\u043e\u0433-\u043f\u0440\u0435\u043e\u0431\u0440\u0430\u0437\u043e\u0432\u0430\u043d\u043d\u0430\u044f (log10(x+1)) \u0432\u0435\u0440\u0441\u0438\u044f \u043e\u043f\u0438\u0441\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0445 \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a \u0438 \u0433\u0438\u0441\u0442\u043e\u0433\u0440\u0430\u043c\u043c. \u041e\u0431\u043e\u0441\u043d\u043e\u0432\u0430\u043d\u0438\u0435: KW/MW/\u0421\u043f\u0438\u0440\u043c\u0435\u043d \u0438\u043d\u0432\u0430\u0440\u0438\u0430\u043d\u0442\u043d\u044b \u043a \u043c\u043e\u043d\u043e\u0442\u043e\u043d\u043d\u044b\u043c \u043f\u0440\u0435\u043e\u0431\u0440\u0430\u0437\u043e\u0432\u0430\u043d\u0438\u044f\u043c, \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u043f\u0440\u0435\u043e\u0431\u0440\u0430\u0437\u043e\u0432\u0430\u043d\u0438\u0435 \u0432\u043b\u0438\u044f\u0435\u0442 \u0442\u043e\u043b\u044c\u043a\u043e \u043d\u0430 \u043e\u043f\u0438\u0441\u0430\u043d\u0438\u044f \u0438 \u0432\u0438\u0437\u0443\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438; \u0432\u044b\u0432\u043e\u0434\u044b \u0441\u0442\u0440\u043e\u044f\u0442\u0441\u044f \u043d\u0430 \u0440\u0430\u043d\u0433\u043e\u0432\u044b\u0445 \u0442\u0435\u0441\u0442\u0430\u0445.\n(f) \u041f\u0440\u043e\u043f\u0443\u0441\u043a\u0438: per-test listwise \u0441 \u0443\u043a\u0430\u0437\u0430\u043d\u0438\u0435\u043c N \u0432 \u043a\u0430\u0436\u0434\u043e\u0439 \u0441\u0442\u0440\u043e\u043a\u0435 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u043e\u0432.\n\n\u2550\u2550\u2550 6. \u041e\u0421\u0423\u0429\u0415\u0421\u0422\u0412\u0418\u041c\u041e\u0421\u0422\u042c \u0418 \u0413\u0420\u0410\u041d\u0418\u0426\u042b \u2550\u2550\u2550\n\u0418\u0441\u043f\u043e\u043b\u043d\u0438\u043c\u043e \u0421\u0415\u0419\u0427\u0410\u0421 (stdlib: csv, re, statistics, json \u2014 \u043f\u0440\u043e\u0432\u0435\u0440\u0435\u043d\u043e): \u0447\u0442\u0435\u043d\u0438\u0435 CSV/TSV; C2 (\u0434\u0443\u0431\u043b\u0438 \u043a\u0430\u043a \u0441\u0442\u0440\u043e\u043a\u0438), \u0447\u0430\u0441\u0442\u0438\u0447\u043d\u044b\u0439 C1 (C6-\u0444\u0438\u043b\u044c\u0442\u0440 \u0444\u043e\u0440\u043c\u0430\u0442\u0430); \u0435\u0441\u043b\u0438 \u0432 \u0434\u0430\u043d\u043d\u044b\u0445 \u0435\u0441\u0442\u044c \u043a\u043e\u043b\u043e\u043d\u043a\u0430 \u0444\u043e\u0440\u043c\u0443\u043b\u044b \u2014 \u043f\u0430\u0440\u0441\u0438\u043d\u0433 Hill-\u0444\u043e\u0440\u043c\u0443\u043b\u044b \u0438 \u0441\u0440\u0435\u0434\u043d\u044f\u044f \u043c\u0430\u0441\u0441\u0430 \u043f\u043e \u0442\u0430\u0431\u043b\u0438\u0446\u0435 \u0438\u0437\u043e\u0442\u043e\u043f\u043d\u044b\u0445 \u0432\u0435\u0441\u043e\u0432. \u041f\u0420\u041e\u0411\u042b (\u043d\u0435 \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442): \u00abC9H8O4\u00bb\u2192180.16, \u00abC8H10N4O2\u00bb\u2192194.19, \u00abC2H6O\u00bb\u219246.07, \u00abC6H12O6\u00bb\u2192180.16, \u00abC6H6\u00bb\u219278.11 \u2014 \u0442\u043e\u0447\u043d\u044b\u0435 \u0441\u043e\u0432\u043f\u0430\u0434\u0435\u043d\u0438\u044f \u0441 \u044d\u0442\u0430\u043b\u043e\u043d\u043d\u044b\u043c\u0438 \u043c\u0430\u0441\u0441\u0430\u043c\u0438; SMILES-charset \u0444\u0438\u043b\u044c\u0442\u0440 \u043a\u043e\u0440\u0440\u0435\u043a\u0442\u043d\u043e \u043e\u0442\u0432\u0435\u0440\u0433 \u0431\u0438\u0442\u044b\u0435 \u0441\u043a\u043e\u0431\u043a\u0438/\u0441\u0438\u043c\u0432\u043e\u043b\u044b/\u043f\u0443\u0441\u0442\u044b\u0435 \u0441\u0442\u0440\u043e\u043a\u0438. \u042f\u0432\u043d\u0430\u044f \u0433\u0440\u0430\u043d\u0438\u0446\u0430: logP (Crippen), TPSA (TopoPSA), Lipinski-SMARTS, \u043a\u0430\u043d\u043e\u043d\u0438\u043d\u0438\u0437\u0430\u0446\u0438\u044f \u0438 Morgan-\u043e\u0442\u043f\u0435\u0447\u0430\u0442\u043a\u0438 \u0432 stdlib \u041d\u0415 \u0432\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u044f\u0442\u0441\u044f \u2014 \u043f\u043e\u0434\u043c\u0435\u043d\u044b \u043d\u0435\u0442; stdlib-\u043c\u0438\u043d\u0438\u043c\u0443\u043c \u0441\u043b\u0443\u0436\u0438\u0442 \u0434\u043b\u044f test-harness'\u0430 \u0438 dry-run, \u043d\u0435 \u0434\u043b\u044f \u043d\u0430\u0443\u0447\u043d\u043e\u0433\u043e \u0432\u044b\u0432\u043e\u0434\u0430.\n\u0422\u0440\u0435\u0431\u0443\u0435\u0442 \u043e\u043a\u0440\u0443\u0436\u0435\u043d\u0438\u044f \u0441 RDKit: \u0432\u0435\u0441\u044c \u0441\u043f\u0438\u0441\u043e\u043a \u0441\u0432\u043e\u0439\u0441\u0442\u0432 \u043f.3, \u043a\u0430\u043d\u043e\u043d\u0438\u043d\u0438\u0437\u0430\u0446\u0438\u044f, Tanimoto.\n\u0417\u0430\u0442\u0440\u0430\u0442\u044b: \u0441\u043b\u043e\u0436\u043d\u043e\u0441\u0442\u044c \u043b\u0438\u043d\u0435\u0439\u043d\u0430 \u043f\u043e N \u0441\u0442\u0440\u043e\u043a; \u0444\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u0437\u0430\u043c\u0435\u0440\u043e\u0432 \u043d\u0435 \u0434\u0435\u043b\u0430\u043b\u043e\u0441\u044c; \u0431\u044e\u0434\u0436\u0435\u0442 \u0432\u0440\u0435\u043c\u0435\u043d\u0438 \u0437\u0430\u043a\u0430\u0437\u0447\u0438\u043a\u043e\u043c \u043d\u0435 \u0437\u0430\u0434\u0430\u043d \u2014 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u043c \u043a\u0430\u043a \u043d\u0435\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u043e\u0441\u0442\u044c \u0431\u0435\u0437 \u043e\u0446\u0435\u043d\u043a\u0438 \u00ab\u0441\u0435\u043a\u0443\u043d\u0434\u044b/\u043c\u0438\u043d\u0443\u0442\u044b\u00bb. \u0420\u0438\u0441\u043a \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0438\u043c\u043e\u0441\u0442\u0438: wheels RDKit \u043f\u043e\u0434 Python 3.14 \u043d\u0435 \u0432\u0435\u0440\u0438\u0444\u0438\u0446\u0438\u0440\u043e\u0432\u0430\u043d\u044b (\u0432 \u0446\u0435\u043b\u0435\u0432\u043e\u043c \u043e\u043a\u0440\u0443\u0436\u0435\u043d\u0438\u0438 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u044c conda-forge/\u043f\u043e\u0434\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0435\u043c\u0443\u044e \u0432\u0435\u0440\u0441\u0438\u044e Python).\n\n\u2550\u2550\u2550 7. \u041e\u0422\u0427\u0401\u0422\u041d\u041e\u0421\u0422\u042c \u2550\u2550\u2550\n\u0411\u0435\u0437 matplotlib \u2014 \u0442\u0430\u0431\u043b\u0438\u0447\u043d\u043e-\u0442\u0435\u043a\u0441\u0442\u043e\u0432\u044b\u0439 \u0444\u043e\u0440\u043c\u0430\u0442: (1) descriptors.csv (id, smiles_input, smiles_canonical, \u0432\u0441\u0435 \u0441\u0432\u043e\u0439\u0441\u0442\u0432\u0430, \u0444\u043b\u0430\u0433\u0438 QC: parsed/dup/sanity/dropped); (2) QC-\u043e\u0442\u0447\u0451\u0442 markdown (\u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u044b C1\u2013C5 \u0441 \u0447\u0438\u0441\u043b\u0430\u043c\u0438 N \u0438 \u0434\u043e\u043b\u044f\u043c\u0438); (3) \u0441\u0432\u043e\u0434\u043d\u044b\u0435 \u0442\u0430\u0431\u043b\u0438\u0446\u044b: \u043e\u043f\u0438\u0441\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u043c\u0435\u0434\u0438\u0430\u043d\u0430 [Q1\u2013Q3]; \u043c\u0430\u0442\u0440\u0438\u0446\u0430 \u0421\u043f\u0438\u0440\u043c\u0435\u043d\u0430; \u0442\u0430\u0431\u043b\u0438\u0446\u0430 KW/MW \u0441 p, q_BH, Cliff's \u03b4, N. \u041f\u0440\u0438 \u043d\u0430\u043b\u0438\u0447\u0438\u0438 \u0431\u0438\u0431\u043b\u0438\u043e\u0442\u0435\u043a \u043a\u043e\u0440\u0440\u0435\u043a\u0442\u043d\u044b: \u0433\u0438\u0441\u0442\u043e\u0433\u0440\u0430\u043c\u043c\u044b (FD-\u0431\u0438\u043d\u044b, \u043b\u0438\u043d\u0435\u0439\u043d\u0430\u044f \u0438 log-\u043e\u0441\u0438), boxplot \u043f\u043e \u0433\u0440\u0443\u043f\u043f\u0430\u043c (\u043f\u0440\u0438 \u043d\u0430\u043b\u0438\u0447\u0438\u0438 group), heatmap Spearman-\u043a\u043e\u0440\u0440\u0435\u043b\u044f\u0446\u0438\u0439, \u043f\u0430\u0440\u043d\u044b\u0435 hexbin-\u0440\u0430\u0441\u0441\u0435\u0438 \u0434\u043b\u044f |\u03c1|>0.8, \u043f\u0440\u0438 \u0437\u0430\u043f\u0440\u043e\u0441\u0435 \u2014 Tanimoto heatmap.\n\n\u2550\u2550\u2550 8. \u0426\u0415\u041b\u041e\u0421\u0422\u041d\u041e\u0421\u0422\u042c \u2550\u2550\u2550\n\u041d\u0438\u043a\u0430\u043a\u0438\u0445 \u0441\u0433\u0435\u043d\u0435\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0445 \u00ab\u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u043e\u0432\u00bb, \u043f\u0440\u0430\u0432\u0434\u043e\u043f\u043e\u0434\u043e\u0431\u043d\u044b\u0445 \u0447\u0438\u0441\u0435\u043b \u0438\u043b\u0438 \u0438\u043b\u043b\u044e\u0441\u0442\u0440\u0430\u0442\u0438\u0432\u043d\u044b\u0445 \u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0439. \u0415\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u0434\u043e\u043f\u0443\u0441\u0442\u0438\u043c\u044b\u0439 \u0437\u0430\u043f\u0443\u0441\u043a \u2014 dry-run \u043a\u043e\u043d\u0432\u0435\u0439\u0435\u0440\u0430 \u043d\u0430 \u0441\u0438\u043d\u0442\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u043c CSV (3\u20135 SMILES), \u0442\u043e\u043b\u044c\u043a\u043e \u0441 \u043c\u0430\u0440\u043a\u0438\u0440\u043e\u0432\u043a\u043e\u0439 \u00abSYNTHETIC DRY-RUN \u2014 \u0438\u043d\u0442\u0435\u0440\u043f\u0440\u0435\u0442\u0430\u0446\u0438\u0438 \u043d\u0435 \u043f\u043e\u0434\u043b\u0435\u0436\u0438\u0442\u00bb; \u0435\u0433\u043e \u0446\u0435\u043b\u044c \u2014 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u043f\u0440\u043e\u0445\u043e\u0434\u0430 \u043a\u043e\u0434\u0430, \u0430 \u043d\u0435 \u0441\u0432\u043e\u0439\u0441\u0442\u0432\u0430 \u0432\u0435\u0449\u0435\u0441\u0442\u0432. \u042d\u0442\u0430\u043b\u043e\u043d\u043d\u044b\u0439 \u0442\u0435\u0441\u0442 C5 \u2014 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438. \u041f\u043e\u0440\u043e\u0433 95% \u2014 \u043a\u043e\u043d\u0432\u0435\u043d\u0446\u0438\u044f \u043d\u0430 \u0441\u043e\u0433\u043b\u0430\u0441\u043e\u0432\u0430\u043d\u0438\u0435.\n\n\u0414\u041e\u041f\u0423\u0429\u0415\u041d\u0418\u042f: assumed-\u0441\u0445\u0435\u043c\u0430 CSV \u043f.2; \u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b \u00abSMILES \u043a\u0430\u043a \u0435\u0441\u0442\u044c, \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0439 \u0444\u0440\u0430\u0433\u043c\u0435\u043d\u0442, \u0431\u0435\u0437 pH-\u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u0438\u0437\u0430\u0446\u0438\u0438\u00bb (\u043d\u0435 \u0437\u0430\u0434\u0430\u043d \u0437\u0430\u043a\u0430\u0437\u0447\u0438\u043a\u043e\u043c); 95% \u043f\u043e\u0440\u043e\u0433 \u0438 \u0434\u043e\u043f\u0443\u0441\u043a\u0438 C5 \u2014 \u043a\u043e\u043d\u0432\u0435\u043d\u0446\u0438\u0438; \u00ab\u0431\u0430\u0437\u043e\u0432\u044b\u0435 \u0441\u0432\u043e\u0439\u0441\u0442\u0432\u0430\u00bb = \u0442\u0430\u0431\u043b\u0438\u0446\u0430 \u043f.3. \u041d\u0415\u041e\u041f\u0420\u0415\u0414\u0415\u041b\u0401\u041d\u041d\u041e\u0421\u0422\u0418: \u0434\u0430\u0442\u0430\u0441\u0435\u0442 (\u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a/\u0444\u043e\u0440\u043c\u0430\u0442/\u0440\u0430\u0437\u043c\u0435\u0440) \u043d\u0435 \u043f\u0440\u0435\u0434\u043e\u0441\u0442\u0430\u0432\u043b\u0435\u043d; \u0433\u0440\u0443\u043f\u043f\u0438\u0440\u043e\u0432\u043a\u0438 \u043d\u0435\u0442 \u2014 \u0433\u0440\u0443\u043f\u043f\u043e\u0432\u043e\u0439 \u0430\u043d\u0430\u043b\u0438\u0437 \u0443\u0441\u043b\u043e\u0432\u043d\u044b\u0439; \u043e\u0436\u0438\u0434\u0430\u0435\u043c\u044b\u0439 \u044d\u043c\u043f\u0438\u0440\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u0438 \u0431\u044e\u0434\u0436\u0435\u0442 \u0432\u0440\u0435\u043c\u0435\u043d\u0438 \u043d\u0435 \u0437\u0430\u0434\u0430\u043d\u044b \u0438 \u043d\u0435 \u043d\u0430\u0437\u043d\u0430\u0447\u0430\u043b\u0438\u0441\u044c; \u0441\u043e\u0432\u043c\u0435\u0441\u0442\u0438\u043c\u043e\u0441\u0442\u044c RDKit\u00d7Python 3.14 \u043d\u0435 \u043f\u0440\u043e\u0432\u0435\u0440\u0435\u043d\u0430; Tanimoto-\u0430\u043d\u0430\u043b\u0438\u0437 \u0432\u043a\u043b\u044e\u0447\u0430\u0435\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u043e \u044f\u0432\u043d\u043e\u043c\u0443 \u0437\u0430\u043f\u0440\u043e\u0441\u0443.", "assumptions": ["\u0414\u0430\u0442\u0430\u0441\u0435\u0442 \u0431\u0443\u0434\u0435\u0442 \u043f\u0435\u0440\u0435\u0434\u0430\u043d \u043f\u043e assumed-\u0441\u0445\u0435\u043c\u0435: CSV/TSV \u0441 \u0437\u0430\u0433\u043e\u043b\u043e\u0432\u043a\u043e\u043c, UTF-8, \u043a\u043e\u043b\u043e\u043d\u043a\u0430 SMILES (+\u043e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e id \u0438 group)", "\u041f\u0440\u043e\u0442\u043e\u043a\u043e\u043b \u043f\u043e\u0434\u0433\u043e\u0442\u043e\u0432\u043a\u0438: SMILES \u043a\u0430\u043a \u0435\u0441\u0442\u044c, \u0441\u043c\u0435\u0441\u0438/\u0441\u043e\u043b\u0438 \u2014 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0439 \u0444\u0440\u0430\u0433\u043c\u0435\u043d\u0442, \u0431\u0435\u0437 \u043f\u0440\u043e\u0442\u043e\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f \u043f\u0440\u0438 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u043c pH, \u0431\u0435\u0437 \u0442\u0430\u0443\u0442\u043e\u043c\u0435\u0440\u043d\u043e\u0439 \u043a\u0430\u043d\u043e\u043d\u0438\u043d\u0438\u0437\u0430\u0446\u0438\u0438 \u2014 \u043f\u0440\u0438\u043d\u044f\u0442 \u043a\u0430\u043a assumption, \u0437\u0430\u043a\u0430\u0437\u0447\u0438\u043a\u043e\u043c \u043d\u0435 \u0437\u0430\u0434\u0430\u043d", "\u00ab\u0411\u0430\u0437\u043e\u0432\u044b\u0435 \u0441\u0432\u043e\u0439\u0441\u0442\u0432\u0430\u00bb = \u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u043f\u0435\u0440\u0435\u0447\u0435\u043d\u044c \u0438\u0437 \u0442\u0430\u0431\u043b\u0438\u0446\u044b \u043f.3, Tanimoto \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u043e \u044f\u0432\u043d\u043e\u043c\u0443 \u0437\u0430\u043f\u0440\u043e\u0441\u0443", "\u041f\u043e\u0440\u043e\u0433 \u043f\u0440\u0438\u0433\u043e\u0434\u043d\u043e\u0441\u0442\u0438 95% \u043f\u0430\u0440\u0441\u0438\u043d\u0433\u0430, \u0434\u043e\u043f\u0443\u0441\u043a\u0438 \u044d\u0442\u0430\u043b\u043e\u043d\u043d\u043e\u0433\u043e \u0442\u0435\u0441\u0442\u0430 \u0438 \u043f\u043e\u0440\u043e\u0433\u0438 Cliff's delta \u2014 \u0441\u043e\u0433\u043b\u0430\u0441\u0443\u0435\u043c\u044b\u0435 \u043a\u043e\u043d\u0432\u0435\u043d\u0446\u0438\u0438, \u043d\u0435 \u044d\u043c\u043f\u0438\u0440\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u0432\u0435\u043b\u0438\u0447\u0438\u043d\u044b", "\u0420\u0430\u0441\u0447\u0451\u0442 \u0432\u044b\u043f\u043e\u043b\u043d\u044f\u0435\u0442\u0441\u044f \u0432 \u043e\u043a\u0440\u0443\u0436\u0435\u043d\u0438\u0438 \u0441 RDKit (\u0432\u0435\u0440\u0441\u0438\u044f \u043f\u0438\u043d\u0438\u0442\u0441\u044f); \u0442\u0435\u043a\u0443\u0449\u0430\u044f \u043f\u0435\u0441\u043e\u0447\u043d\u0438\u0446\u0430 \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u043d\u0430\u043f\u0438\u0441\u0430\u043d\u0438\u0435 \u043a\u043e\u0434\u0430 \u0438 dry-run \u043d\u0430 \u0437\u0430\u0433\u043b\u0443\u0448\u043a\u0430\u0445"], "evidence": "\u041e\u0441\u043c\u043e\u0442\u0440 \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u044f: /workspace \u0441\u043e\u0434\u0435\u0440\u0436\u0438\u0442 \u0442\u043e\u043b\u044c\u043a\u043e task.json (378 \u0431\u0430\u0439\u0442; \"Design-only task; repositories and compute are not required\"); datasets=[]; \u0445\u0438\u043c\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u0434\u0430\u0442\u0430\u0441\u